// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    function testFuzz_property(address from, uint256 v, uint8 tosCount) public {
        tosCount = uint8(bound(tosCount, 1, 5));

        ReceiverGood good = new ReceiverGood();
        ReceiverBad bad = new ReceiverBad();

        address[] memory tos = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) {
            tos[i] = (i % 2 == 0) ? address(good) : address(bad);
        }

        address[] memory tosAllGood = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) tosAllGood[i] = address(good);

        bool ok;
        try c.transfer(from, address(good), tosAllGood, v) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract ReceiverGood {
    event Called(bytes4 sig, address from, address to, uint256 v);
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Called(bytes4(keccak256("transferFrom(address,address,uint256)")), from, to, v);
        return true;
    }
}

contract ReceiverBad {
    event Called(bytes4 sig, address a, address b, uint256 v);
    function transfer(address a, address b, uint256 v) external returns (bool) {
        emit Called(bytes4(keccak256("transfer(address,address,uint256)")), a, b, v);
        return true;
    }
}
